{
  "similarities": [
    {
      "point": "Both texts discuss measurement units derived from the human body.",
      "quote_britannica": "Barley-corn & 3 Inch & \\multicolumn{4}{c}{1 ENGLISH.}",
      "quote_wikipedia": "This is a list of units of measurement based on human body parts or the attributes and abilities of humans"
    },
    {
      "point": "Both texts include the cubit as a unit of measurement.",
      "quote_britannica": "54 & 18 & 6 & 2 & Cubit & \\\\",
      "quote_wikipedia": "Cubit - length of the human forearm"
    },
    {
      "point": "Both texts include the span as a unit of measurement.",
      "quote_britannica": "27 & 9 & 9 & Span & & \\\\",
      "quote_wikipedia": "Span - width of a human hand, from the tip of the thumb to the tip of the little finger"
    },
    {
      "point": "Both texts include the palm as a unit of measurement.",
      "quote_britannica": "9 & 9 & 3 & Palm & & \\\\",
      "quote_wikipedia": "Palm - breadth of four fingers"
    }
  ],
  "differences": [
    {
      "point": "Britannica provides conversion tables for ancient units into English feet, while Wikipedia provides a descriptive list of units.",
      "quote_britannica": "23760 & 7920 & 2640 & 880 & 660 & 440\\\\",
      "quote_wikipedia": "Morgen - the area that one man could plow from morning to noon"
    },
    {
      "point": "Britannica focuses on specific regional measures like the Paris ell, while Wikipedia lists globally diverse anthropometric units.",
      "quote_britannica": "cobres ten wherever are equal to three Paris ella.",
      "quote_wikipedia": "A cross-cultural review of body-based measurement systems has found such units to be ubiquitous worldwide."
    }
  ],
  "claims": [
    {
      "claim": "The cubit is equal to 2 feet.",
      "tag": "enduring",
      "quote_britannica": "54 & 18 & 6 & 2 & Cubit & \\\\",
      "quote_wikipedia": "Cubit - length of the human forearm"
    },
    {
      "claim": "The span is equal to 9 inches.",
      "tag": "enduring",
      "quote_britannica": "27 & 9 & 9 & Span & & \\\\",
      "quote_wikipedia": "Span - width of a human hand, from the tip of the thumb to the tip of the little finger"
    },
    {
      "claim": "The palm is equal to 3 inches.",
      "tag": "enduring",
      "quote_britannica": "9 & 9 & 3 & Palm & & \\\\",
      "quote_wikipedia": "Palm - breadth of four fingers"
    },
    {
      "claim": "The fathom is equal to 6 feet.",
      "tag": "enduring",
      "quote_britannica": "216 & 72 & 24 & 8 & 6 & 3 Fathora\\\\",
      "quote_wikipedia": "Fathom - the distance between the fingertips of a human's outstretched arms"
    },
    {
      "claim": "The yard is equal to 3 feet.",
      "tag": "enduring",
      "quote_britannica": "108 & 36 & 12 & 4 & 3 & Yard\\\\",
      "quote_wikipedia": "Ell (Scots) - length of an average person's arm"
    },
    {
      "claim": "The pace is equal to 3 feet.",
      "tag": "enduring",
      "quote_britannica": "180 & 60 & 20 & 63 & 31 & Pace\\\\",
      "quote_wikipedia": "Pace - a full stride, from heel to heel"
    },
    {
      "claim": "The digit is a unit of measurement.",
      "tag": "enduring",
      "quote_britannica": "Digit & & & & & Eng-feet & Dec\\\\",
      "quote_wikipedia": "Digit - length of a human finger"
    },
    {
      "claim": "The Arabian pole is a unit of measurement.",
      "tag": "dropped",
      "quote_britannica": "192 48 16 8 2 13 Arabian pole & & & & & 14 & 7.104\\\\",
      "quote_wikipedia": null
    }
  ],
